/* NASA Blue Marble (Visible Earth, public domain), 1024x512 equirectangular.
   Inlined as a data URI: a local <img> would taint the canvas under file://
   and getImageData() would throw, so the texture could not be sampled. */
window.JK_GEO = window.JK_GEO || {};
window.JK_GEO.earth = "data:image/jpeg;base64,";
